import React from 'react';
import "./CheckoutForm.scss";
import {Formik, Form, Field} from "formik";
import * as Yup from "yup";
import {useNavigate} from "react-router-dom";

const CheckoutForm = () => {
    const navigate = useNavigate();
    const checkoutSchema = Yup.object().shape({
        firstName: Yup.string()
            .min(2, 'Too Short!')
            .max(50, 'Too Long!')
            .required('Required'),
        lastName: Yup.string()
            .min(2, 'Too Short!')
            .max(50, 'Too Long!')
            .required('Required'),
        email: Yup.string()
            .email('Invalid email')
            .required('Required'),
        phone: Yup.string()
            .matches(/^[0-9]+$/, 'Invalid phone number')
            .min(10, 'Too Short!')
            .max(15, 'Too Long!')
            .required('Required'),
        address: Yup.string()
            .min(5, 'Too Short!')
            .max(50, 'Too Long!')
            .required('Required'),
    });

    const handleSubmit = (values: any) => {
        console.log(values);
        navigate('/');
    }
    return (
        <Formik
            initialValues={{
                firstName: '',
                lastName: '',
                email: '',
                phone: '',
                address: ''
            }}
            onSubmit={(values, { resetForm}) => {
                handleSubmit(values);
                resetForm();
            }}>
            {({errors, touched}) => (
                <Form className={"checkout-form"}>
                    <div className={'form-field'}>
                        <label>First name</label>
                        <Field name="firstName" type="text"/>
                        {errors.firstName && touched.firstName && <div className={'error-message'}>{errors.firstName}</div>}
                    </div>
                    <div className={'form-field'}>
                        <label>Last name</label>
                        <Field name="lastName" type="text"/>
                        {errors.lastName && touched.lastName && <div className={'error-message'}>{errors.lastName}</div>}
                    </div>
                    <div className={'form-field'}>
                        <label>Email</label>
                        <Field name="email" type="email"/>
                        {errors.email && touched.email && <div className={'error-message'}>{errors.email}</div>}
                    </div>
                    <div className={'form-field'}>
                        <label>Phone</label>
                        <Field name="phone" type="text"/>
                        {errors.phone && touched.phone && <div className={'error-message'}>{errors.phone}</div>}
                    </div>
                    <div className={'form-field'}>
                        <label>Address</label>
                        <Field name="address" type="text"/>
                        {errors.address && touched.address && <div className={'error-message'}>{errors.address}</div>}
                    </div>
                    <button type="submit" className={'submit-button'}>Submit</button>
                </Form>
            )}
        </Formik>
    );
};

export default CheckoutForm;
